210:   <div class="pic poster-media">
211:     <img class="poster-img" src="https://image.tmdb.org/t/p/w780/xOMo8BRK7PfcJv9JCnx7s520dQe.jpg" alt="Dune: Part Two" loading="lazy" decoding="async">
212:     <span class="chip poster-rating-badge">★ 8.6</span>
213:     <b class="ttl poster-title">Dune: Part Two</b>
214:   </div>
215:   <div class="cap poster-meta">2024 · Movie · Sci-Fi</div>
216: </div>
217: ```
