307: ### Requirement 5: Dynamic Backdrop Art Swap Trigger When Hero Updates or Card is Focused
308: 
309: #### 5.1 Dual-Buffer Canvas Setup (`app/index.html` lines 17–26)
310: ```html
311: <div id="bg" class="bg-backdrop-container" aria-hidden="true">
312:   <img id="bgA" class="bg-backdrop-img on" alt="" aria-hidden="true">
313:   <img id="bgB" class="bg-backdrop-img" alt="" aria-hidden="true">
314: </div>
315: <img id="bgBlur" class="bg-blur-backdrop" alt="" aria-hidden="true">
316: <div id="shade" class="shade dual-gradient-overlay" aria-hidden="true"></div>
317: ```
318: 
319: #### 5.2 Alternating Crossfade Engine (`setBg`)
320: ```javascript
321: var bgFlip = false;
322: var lastBg = null;
323: 
324: function setBg(src) {
325:   if (!src || src === lastBg) return;
326:   lastBg = src;
327:   var bgA = document.getElementById('bgA');
328:   var bgB = document.getElementById('bgB');
329:   var bgBlur = document.getElementById('bgBlur');
330:   if (!bgA || !bgB) return;
331: 
332:   var on = bgFlip ? bgA : bgB;
333:   var off = bgFlip ? bgB : bgA;
334:   bgFlip = !bgFlip;
335: 
336:   on.onload = function () {
337:     on.classList.add('on');
338:     off.classList.remove('on');
339:   };
340:   on.src = src;
341: 
342:   if (bgBlur) {
343:     bgBlur.src = src;
344:   }
345: }
346: ```
347: 
348: #### 5.3 300ms Debounced Focus Trigger (`bgFor`)
349: When holding a remote D-pad arrow key, rapid focus events fire every ~60ms. Without debouncing, the TV decoder attempts to fetch and decode dozens of 1280px images simultaneously, leading to memory saturation and dropped frames on the LG 1.5GB RAM hardware.
350: ```javascript
351: var bgTimer = null;
352: 
353: function bgFor(itemOrUrl) {
354:   clearTimeout(bgTimer);
355:   bgTimer = setTimeout(function () {
356:     var url = typeof itemOrUrl === 'string' ? itemOrUrl : (itemOrUrl && (itemOrUrl.backdropUrl || itemOrUrl.bg));
357:     if (!url && HomeViewController.heroItems && HomeViewController.heroItems.length) {
358:       var currentHero = HomeViewController.heroItems[HomeViewController.heroIdx];
359:       url = currentHero ? (currentHero.backdropUrl || currentHero.bg) : null;
360:     }
361:     if (url) {
362:       setBg(url);
363:     }
364:   }, 300);
365: }
366: ```
367: 
368: #### 5.4 Event Wiring in Home View
369: 1. **Hero Mount / Carousel Rotate**: Immediate invocation of `setBg(heroItem.backdropUrl)`.
370: 2. **Card Focus**: Registered on `SpatialNav` focus event:
371:    ```javascript
372:    if (global.SpatialNav && typeof global.SpatialNav.on === 'function') {
373:      global.SpatialNav.on('focus', function (evt) {
374:        var el = evt.element;
375:        if (!el) return;
376:        if (el.id === 'heroBtn' || el.closest('#hero')) {
377:          var hItem = HomeViewController.heroItems[HomeViewController.heroIdx];
378:          if (hItem) bgFor(hItem.backdropUrl);
379:        } else if (el.classList.contains('card') || el.classList.contains('card-poster')) {
380:          var backdrop = el.getAttribute('data-backdrop');
381:          if (backdrop) bgFor(backdrop);
382:        }
383:      });
384:    }
385:    ```
