/* ==========================================================================
   Hero Banner & Google TV Spotlight (#hero, 10-Foot Ergonomics)
   ========================================================================== */
#hero {
  position: relative;
  height: 640px;
  padding-top: 196px;
  width: 1000px;
  max-width: 1000px;
  transition: opacity .3s;
}

.hero-banner {
  position: relative;
  width: 100%;
  height: var(--hero-banner-height, 640px);
  overflow: hidden;
  display: flex;
  align-items: flex-end;
  padding-bottom: 48px;
  padding-left: var(--tv-safe-x);
  padding-right: var(--tv-safe-x);
  transition: opacity .3s;
}

#heroSrc {
  font-size: 22px;
  color: #bdc1c6;
  margin-bottom: 14px;
  height: 26px;
  letter-spacing: .3px;
}

#heroTitle {
  font-size: 72px;
  font-weight: 500;
  line-height: 1.04;
  margin-bottom: 14px;
  max-height: 150px;
  overflow: hidden;
  color: #e8eaed;
}

#heroMeta {
  font-size: 22px;
  color: #bdc1c6;
  margin-bottom: 14px;
}

#heroSub {
  font-size: 24px;
  color: #dadce0;
  line-height: 1.4;
  max-height: 68px;
  overflow: hidden;
  width: 860px;
  max-width: 860px;
}

#heroBtn,
.hero-play-btn {
  display: inline-block;
  margin-top: 26px;
  padding: 14px 34px;
  border-radius: 30px;
  font-size: 24px;
  font-weight: 500;
  background: rgba(232, 234, 237, 0.16);
  color: #e8eaed;
  transition: background .15s, color .15s, transform .15s;
  cursor: pointer;
  border: none;
  text-decoration: none;
}

#heroBtn.focus,
#heroBtn.focused,
.hero-play-btn.focus,
.hero-play-btn.focused {
  background: #e8eaed;
  color: #202124;
  transform: scale(1.05);
}

#dots {
  position: absolute;
  left: 1700px;
  top: 560px;
  white-space: nowrap;
}

#dots i {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.35);
  margin-left: 10px;
  transition: width .3s, background .3s;
}

#dots i.on {
  width: 28px;
  background: #fff;
}

.scrolled #hero,
body.scrolled #hero,
.scrolled .hero-banner,
body.scrolled .hero-banner {
  opacity: 0;
}

.hero-backdrop-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.hero-backdrop-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 20%;
  transition: opacity 0.9s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.hero-gradient-overlay {
  position: absolute;
  inset: 0;
  z-index: 2;
  background: 
    linear-gradient(90deg, rgba(14, 16, 20, 0.96) 0%, rgba(14, 16, 20, 0.75) 35%, rgba(14, 16, 20, 0.25) 65%, rgba(14, 16, 20, 0) 100%),
    linear-gradient(0deg, #0e1014 10%, rgba(14, 16, 20, 0.75) 45%, rgba(14, 16, 20, 0.20) 70%, rgba(14, 16, 20, 0) 100%);
}

.hero-content {
  position: relative;
  z-index: 3;
  max-width: 960px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.hero-logo-box {
  min-height: 80px;
  max-height: 130px;
  display: flex;
  align-items: flex-end;
}

.hero-clear-logo {
  max-height: 110px;
  max-width: 480px;
  object-fit: contain;
  object-position: left bottom;
  filter: drop-shadow(0 4px 16px rgba(0, 0, 0, 0.85));
}

.hero-title-fallback {
  font-family: var(--font-family-headings);
  font-size: 72px;
  font-weight: 500;
  line-height: 1.04;
  margin-bottom: 14px;
  max-height: 150px;
  overflow: hidden;
  color: var(--color-text-primary);
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.9);
}

.hero-meta-row {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 22px;
  color: var(--color-text-secondary);
}

.badge-pill {
  padding: 4px 14px;
  border-radius: var(--radius-pill);
  background-color: var(--cinema-surface-pill, rgba(60, 64, 67, 0.55));
  border: 1px solid rgba(255, 255, 255, 0.12);
  font-weight: var(--font-weight-semibold);
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--cinema-text-primary, #e8eaed);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.badge-pill.rating {
  color: var(--color-star, #FACC15);
  border-color: rgba(250, 204, 21, 0.35);
  background-color: rgba(250, 204, 21, 0.12);
}

.badge-pill.accent {
  color: var(--color-accent-primary, #95FF50);
  border-color: rgba(149, 255, 80, 0.40);
  background-color: rgba(149, 255, 80, 0.12);
}

.hero-synopsis {
  font-size: 24px;
  color: #dadce0;
  line-height: 1.4;
  max-height: 68px;
  overflow: hidden;
  width: 860px;
  max-width: 860px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.85);
}

.hero-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 6px;
}

/* Action Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-family: var(--font-family-base);
  font-size: var(--font-size-body);
  font-weight: var(--font-weight-medium);
  border-radius: var(--radius-pill);
  cursor: pointer;
  border: 2px solid transparent;
  transition: all 0.2s ease;
  text-decoration: none;
}

.btn svg {
  width: 22px;
  height: 22px;
}

.btn-primary {
  height: 52px;
  padding: 0 32px;
  background-color: var(--color-accent-primary);
  color: #04120B;
  font-weight: var(--font-weight-bold);

