/* ==========================================================================
   Content Shelves & Headers (.row, .strip - 262px Strip Architecture)
   ========================================================================== */
.row,
.content-shelf {
  margin-bottom: 18px;
  position: relative;
}

.row h3,
.shelf-title {
  font-family: var(--font-family-headings);
  font-size: 24px;
  font-weight: 500;
  margin-bottom: 18px;
  color: #e8eaed;
  letter-spacing: -0.01em;
}

.strip,
.shelf-rail {
  white-space: nowrap;
  height: 262px;
  will-change: transform;
  contain: layout style;
  transition: transform .35s cubic-bezier(.2, .8, .2, 1);
}

.shelf-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 2px;
}

.shelf-view-all {
  font-size: var(--font-size-caption);
  color: var(--color-text-muted);
  text-decoration: none;
  font-weight: var(--font-weight-medium);
}

/* ==========================================================================
   16:9 Google TV Card Proportions (352px x 198px)
   Legacy baseline reference: width: 220px; height: 330px;
   ========================================================================== */
.card,
.card-poster {
  display: inline-block;
  vertical-align: top;
  position: relative;
  width: 352px;
  width: var(--card-poster-width, 352px);
  margin-right: 26px;
  cursor: pointer;
  text-decoration: none;
  border-radius: var(--cinema-radius-card, 14px);
  outline: none;
  contain: layout style;
  transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1), box-shadow 0.2s ease;
}

.card .pic,
.poster-media {
  position: relative;
  width: 100%;
  width: var(--card-poster-width, 352px);
  height: 198px;
  height: var(--card-poster-height, 198px);
  border-radius: 14px;
  border-radius: var(--cinema-radius-card, 14px);
  overflow: hidden;
  background: #26292f;
  background: var(--cinema-surface-card, #26292f);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.45);
  border: 1px solid var(--color-border-card, rgba(255, 255, 255, 0.12));
  transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1), box-shadow 0.2s ease;
}

.card img,
.poster-img,
.card-poster-img,
.poster-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  background-color: #0b1a11;
}

.card .ttl,
.ttl.poster-title {
  position: absolute;
  left: 16px;
  right: 16px;
  bottom: 12px;
  font-size: 22px;
  font-weight: 500;
  white-space: normal;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.9);
  color: #fff;
  z-index: 2;
}

.card .chip,
.chip.poster-badge,
.chip.poster-rating-badge,
.poster-rating-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 15px;
  font-weight: var(--font-weight-bold);
  color: #fff;
  display: flex;
  align-items: center;
  gap: 4px;
  z-index: 2;
}

.poster-rating-badge svg,
.chip svg {
  width: 12px;
  height: 12px;
  fill: var(--color-star, #FACC15);
}

.card .cap,
.cap.poster-meta,
.cap.poster-info,
.poster-info {
  margin-top: 14px;
  font-size: 20px;
  color: #bdc1c6;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  opacity: 0;
  transition: opacity 0.2s;
  display: block;
  width: 100%;
}

.poster-title {
  font-size: 22px;
  font-weight: 500;
  color: #fff;
}

.poster-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 20px;
  color: #bdc1c6;
}

.poster-meta .dot {
  font-size: 12px;
  color: var(--color-text-muted);
}

/* ==========================================================================
   Focus Elevation & Contact Halo
   ========================================================================== */
.focus .pic,
.focused .pic,
.focus .poster-media,
.focused .poster-media,
.tv-focused .pic,
.tv-focused .poster-media {
  transform: scale(1.1);
  box-shadow: 0 0 0 5px #fff, 0 12px 30px rgba(0, 0, 0, 0.6);
}

.focus .cap,
.focused .cap,
.focus.card .cap,
.focused.card .cap,
.focus .poster-info,
.focused .poster-info,
.focus .poster-meta,
.focused .poster-meta {
  opacity: 1;
  color: #fff;
}

