createPosterCard: function (item, groupName, index, options) {
  if (!item) return document.createComment('empty-card');
  var opts = options || {};
  var card = document.createElement('div');
  card.className = 'card card-poster f';
  card.setAttribute('data-nav', 'true');
  card.setAttribute('data-nav-group', groupName);
  card.setAttribute('data-nav-index', String(index));
  card.setAttribute('tabindex', '0');

  var id = item.id || item.tmdbId || index;
  var mediaType = item.media_type || item.type || opts.mediaType || (item.first_air_date ? 'tv' : 'movie');
  var title = item.title || item.name || 'Untitled';
  var releaseDate = item.release_date || item.first_air_date || item.releaseDate || '';
  var year = String(item.year || releaseDate).slice(0, 4) || '—';
  var rating = item.ratingDisplay || (typeof item.vote_average === 'number' ? item.vote_average.toFixed(1) : (item.vote_average ? String(item.vote_average) : (item.rating ? String(item.rating) : 'NR')));
  var posterPath = item.poster_path || item.posterUrl;
  var posterUrl = item.posterUrl || (posterPath && posterPath.indexOf('http') === 0 ? posterPath : (global.TmdbClient ? global.TmdbClient.getPosterUrl(posterPath) : ('https://image.tmdb.org/t/p/w500' + (posterPath || ''))));
  var backdropPath = item.backdrop_path || item.backdropUrl;
  var backdropUrl = item.backdropUrl || (backdropPath && backdropPath.indexOf('http') === 0 ? backdropPath : (global.TmdbClient ? global.TmdbClient.getBackdropUrl(backdropPath) : ('https://image.tmdb.org/t/p/w1280' + (backdropPath || ''))));

  card.setAttribute('data-id', String(id));
  card.setAttribute('data-type', mediaType);
  card.setAttribute('data-title', title);
  card.setAttribute('data-year', year);
  card.setAttribute('data-rating', rating);
  if (backdropUrl) {
    card.setAttribute('data-backdrop', backdropUrl);
  }

  var genreText = opts.genreText || (Array.isArray(item.genres) && item.genres.length ? item.genres.slice(0, 2).join(', ') : (mediaType === 'tv' ? 'Series' : 'Movie'));

  // DOM Generation with STRICT ZERO DOM SINKS
  // 16:9 Google TV Media Preview Surface (.pic.poster-media)
  var posterMedia = document.createElement('div');
  posterMedia.className = 'pic poster-media';

  var posterImg = document.createElement('img');
  posterImg.className = 'card-poster-img poster-image poster-img';
  posterImg.src = posterUrl;
  posterImg.alt = title;
  posterImg.setAttribute('loading', 'lazy');
  posterImg.onerror = function () {
    if (global.TmdbClient && typeof global.TmdbClient.handleImageError === 'function') {
      global.TmdbClient.handleImageError(this, 'poster');
    } else {
      this.onerror = null;
      this.src = CardFactory.getFallbackPosterSvg();
    }
  };
  posterMedia.appendChild(posterImg);

  if (rating !== 'NR') {
    var ratingBadge = document.createElement('span');
    ratingBadge.className = 'chip poster-badge poster-rating-badge';
    ratingBadge.appendChild(createStarSvg(12, 12));
    ratingBadge.appendChild(document.createTextNode(' ' + rating));
    posterMedia.appendChild(ratingBadge);
  }

  var titleEl = document.createElement('div');
  titleEl.className = 'ttl poster-title';
  titleEl.textContent = title;
  posterMedia.appendChild(titleEl);

  card.appendChild(posterMedia);

  // Resting Caption (reveals on focus in Google TV, persistent in catalog)
  var posterInfo = document.createElement('div');
  posterInfo.className = 'cap poster-meta poster-info';

  var yearSpan = document.createElement('span');
  yearSpan.className = 'poster-year';
  yearSpan.textContent = year;
  posterInfo.appendChild(yearSpan);

  var dotSpan = document.createElement('span');
  dotSpan.className = 'dot';
  dotSpan.textContent = ' • ';
  posterInfo.appendChild(dotSpan);

  var genreSpan = document.createElement('span');
  genreSpan.className = 'poster-genre';
  genreSpan.textContent = genreText;
  posterInfo.appendChild(genreSpan);

  card.appendChild(posterInfo);

  return card;
},

