var bgFlip = false;
var lastBg = null;
var bgTimer = null;

function setBg(src) {
  if (!src || src === lastBg) return;
  lastBg = src;
  var bgA = document.getElementById('bgA');
  var bgB = document.getElementById('bgB');
  var bgBlur = document.getElementById('bgBlur');
  if (!bgA || !bgB) return;

  var on = bgFlip ? bgA : bgB;
  var off = bgFlip ? bgB : bgA;
  bgFlip = !bgFlip;

  on.onload = function () {
    on.classList.add('on');
    off.classList.remove('on');
  };
  on.src = src;

  if (bgBlur) {
    bgBlur.src = src;
  }
}

function bgFor(itemOrUrl) {
  clearTimeout(bgTimer);
  bgTimer = setTimeout(function () {
    var url = typeof itemOrUrl === 'string' ? itemOrUrl : (itemOrUrl && (itemOrUrl.backdropUrl || itemOrUrl.backdrop_path || itemOrUrl.bg));
    if (!url && HomeViewController.heroItems && HomeViewController.heroItems.length) {
      var currentHero = HomeViewController.heroItems[HomeViewController.heroIdx];
      url = currentHero ? (currentHero.backdropUrl || currentHero.backdrop_path || currentHero.bg) : null;
    }
    if (url) {
      if (url.indexOf('http') !== 0 && global.TmdbClient && typeof global.TmdbClient.getBackdropUrl === 'function') {
        url = global.TmdbClient.getBackdropUrl(url);
      }
      setBg(url);
    }
  }, 300);
}

var HomeViewController = {
  initialized: false,
  featuredItem: null,
  container: null,
  heroItems: [],
  heroIdx: 0,
  idleTimer: null,
  idleSince: Date.now(),

  init: function () {
    if (this.initialized) return;
    this.initialized = true;
    this.container = document.getElementById('view-home');
    this.bindActions();
    this.bindNavigationEvents();
  },

  bindActions: function () {
    var self = this;
    var playBtn = document.getElementById('hero-play-btn') || document.getElementById('heroBtn');
    if (playBtn) {
      playBtn.addEventListener('click', function () {
        var item = self.featuredItem || (self.heroItems && self.heroItems[self.heroIdx]);
        if (item && global.CinejoyApp) {
          global.CinejoyApp.switchView('player', {
            tmdbId: item.id || item.tmdbId,
            type: item.media_type || item.type || 'movie',
            title: item.title || item.name
          });
        }
      });
    }

    var detailsBtn = document.getElementById('hero-details-btn');
    if (detailsBtn) {
      detailsBtn.addEventListener('click', function () {
        var item = self.featuredItem || (self.heroItems && self.heroItems[self.heroIdx]);
        if (item && global.CinejoyApp) {
          global.CinejoyApp.openDetails(item);
        }
      });
    }
  },

  bindNavigationEvents: function () {
    var self = this;

    if (global.SpatialNav && typeof global.SpatialNav.on === 'function') {
      global.SpatialNav.on('focus', function (data) {
        self.idleSince = Date.now();
        var el = data && (data.element || data.toElement);
        if (!el) return;
        self.handleElementFocus(el);
      });
    }

    if (this.container) {
      this.container.addEventListener('focusin', function (e) {
        self.idleSince = Date.now();
        if (e.target) {
          self.handleElementFocus(e.target);
        }
      });
    }
  },

  handleElementFocus: function (el) {
    var card = el.closest ? el.closest('.card, .card-poster') : null;
    if (card) {
      var bg = card.getAttribute('data-backdrop');
      if (bg) {
        bgFor(bg);
      }
      var strip = card.closest ? (card.closest('.strip') || card.closest('.shelf-rail')) : null;
      if (strip) {
        var colIdx = parseInt(card.getAttribute('data-nav-index'), 10) || 0;
        var offset = -Math.max(0, card.offsetLeft - (colIdx > 0 ? 40 : 0));
        strip.style.transform = 'translateX(' + offset + 'px)';
      }
    } else if (el.closest && el.closest('#hero, .hero-banner')) {
      if (this.heroItems && this.heroItems.length) {
        var it = this.heroItems[this.heroIdx];
        if (it) {
          bgFor(it.backdropUrl || it.backdrop_path);
        }
      }
    }
  },

  activate: function () {
    this.init();
    this.loadContent();
  },

  loadContent: function () {
    var self = this;
    if (!global.TmdbClient) {
      console.warn('[HomeViewController] TmdbClient unavailable, using existing DOM.');
      return;
    }

    var pTrendingMovies = global.TmdbClient.getTrending('movie', 'day');
    var pTrendingTv = global.TmdbClient.getTrending('tv', 'day');
    var pTopRatedMovies = global.TmdbClient.getTopRated('movie', 1);
    var pTopRatedTv = global.TmdbClient.getTopRated('tv', 1);
    var pCurated = typeof global.TmdbClient.getCuratedLists === 'function' ? global.TmdbClient.getCuratedLists() : (typeof global.TmdbClient.getWingLists === 'function' ? global.TmdbClient.getWingLists() : Promise.resolve([]));

    Promise.all([
      pTrendingMovies,
      pTrendingTv,
      pTopRatedMovies,
      pTopRatedTv,
      pCurated
    ]).then(function (results) {
      var trendingMovies = results[0] && results[0].results ? results[0].results : [];
      var trendingTv = results[1] && results[1].results ? results[1].results : [];
      var topRatedMovies = results[2] && results[2].results ? results[2].results : [];
      var topRatedTv = results[3] && results[3].results ? results[3].results : [];
      var curatedLists = results[4] || [];

      // Top 6 items for Google TV Hero Presentation Carousel
      if (trendingMovies.length > 0) {
        self.heroItems = trendingMovies.slice(0, 6);
        self.heroIdx = 0;
        self.showHero(self.heroItems[0]);
        self.startAutoplay();
      }

      // Render Shelf Rails with dual classes (row content-shelf, strip shelf-rail)
      self.renderShelf('shelf-trending-movies', trendingMovies, 'movie');
      self.renderShelf('shelf-trending-series', trendingTv, 'tv');
      self.renderShelf('shelf-toprated', topRatedMovies, 'movie');
      self.renderShelf('shelf-toprated-tv', topRatedTv, 'tv');
      if (curatedLists.length > 0) {
        self.renderCuratedShelf('shelf-curated', curatedLists);
      }
    }).catch(function (err) {
      console.error('[HomeViewController] Failed to load home content:', err);
    });
  },

  showHero: function (item) {
    var it = item || (this.heroItems && this.heroItems[this.heroIdx]);
    if (!it) return;
    this.featuredItem = it;

    var title = it.title || it.name || 'Featured Title';
    var releaseDate = it.release_date || it.first_air_date || it.releaseDate || '';
    var year = String(it.year || releaseDate).slice(0, 4) || '2024';
    var rating = it.ratingDisplay || (typeof it.vote_average === 'number' ? it.vote_average.toFixed(1) : (it.vote_average ? String(it.vote_average) : (it.rating ? String(it.rating) : '8.6')));
    var backdropPath = it.backdrop_path || it.backdropUrl;
    var backdropUrl = it.backdropUrl || (backdropPath && backdropPath.indexOf('http') === 0 ? backdropPath : (global.TmdbClient ? global.TmdbClient.getBackdropUrl(backdropPath) : 'https://image.tmdb.org/t/p/w1280/xOMo8BRK7PfcJv9JCnx7s520dQe.jpg'));

    var heroSrc = document.getElementById('heroSrc');
    if (heroSrc) {
      var runtimeStr = it.runtime ? (Math.floor(it.runtime / 60) + 'h ' + (it.runtime % 60) + 'm') : '2h 46m';
      heroSrc.textContent = 'Trending ' + (it.media_type === 'tv' ? 'Series' : 'Movie') + ' • ' + year + ' • ' + runtimeStr;
    }

    var heroTitle = document.getElementById('heroTitle') || (this.container && this.container.querySelector('.hero-title-fallback'));
    if (heroTitle) {
      heroTitle.textContent = title;
    }

    var heroMeta = document.getElementById('heroMeta') || (this.container && this.container.querySelector('.hero-meta-row'));
    if (heroMeta) {
      while (heroMeta.firstChild) {
        heroMeta.removeChild(heroMeta.firstChild);
      }
      var rBadge = document.createElement('span');
      rBadge.className = 'badge-pill rating';
      rBadge.appendChild(CardFactory.createStarSvg(14, 14));
      rBadge.appendChild(document.createTextNode(' ' + rating));
      heroMeta.appendChild(rBadge);

      var yBadge = document.createElement('span');
      yBadge.className = 'badge-pill';
      yBadge.textContent = year;
      heroMeta.appendChild(yBadge);

      var qBadge = document.createElement('span');
      qBadge.className = 'badge-pill accent';
      qBadge.textContent = '4K Ultra HD';
      heroMeta.appendChild(qBadge);

      var genreList = Array.isArray(it.genres) && it.genres.length ? it.genres : (it.genre_ids ? ['Sci-Fi', 'Adventure'] : ['Movie']);
      var gBadge = document.createElement('span');
      gBadge.className = 'badge-pill';
      gBadge.textContent = genreList.slice(0, 2).join(' / ');
      heroMeta.appendChild(gBadge);
    }

    var heroSub = document.getElementById('heroSub') || (this.container && this.container.querySelector('.hero-synopsis'));
    if (heroSub) {
      heroSub.textContent = it.overview || 'Paul Atreides unites with Chani and the Fremen while seeking revenge against the conspirators who destroyed his family.';
    }

    var heroBtn = document.getElementById('heroBtn');
    if (heroBtn) {
      heroBtn.textContent = 'Open';
    }

    var dots = document.getElementById('dots');
    if (dots && this.heroItems.length) {
      while (dots.firstChild) {
        dots.removeChild(dots.firstChild);
      }
      for (var i = 0; i < this.heroItems.length; i++) {
        var dot = document.createElement('i');
        if (i === this.heroIdx) {
          dot.className = 'on';
        }
        dots.appendChild(dot);
      }
    }

    if (backdropUrl) {
      setBg(backdropUrl);
    }

    var backdropImg = this.container ? this.container.querySelector('.hero-backdrop-img') : null;
    if (backdropImg && backdropUrl) {
      backdropImg.src = backdropUrl;
    }
  },

  stepHero: function (dir) {
    if (!this.heroItems || !this.heroItems.length) return;
    this.heroIdx = (this.heroIdx + dir + this.heroItems.length) % this.heroItems.length;
    this.showHero(this.heroItems[this.heroIdx]);
  },

  startAutoplay: function () {
    var self = this;
    if (this.idleTimer) clearInterval(this.idleTimer);
    this.idleTimer = setInterval(function () {
      var activeView = document.querySelector('.view.active');
      var isHomeActive = activeView && activeView.id === 'view-home';
      if (isHomeActive && Date.now() - self.idleSince > 7000) {
        self.stepHero(1);
      }
    }, 8000);
  },

  bindHeroBanner: function (item) {
    this.showHero(item);
  },

